E["140:a2a3b660"] = "Порадник зі здобичі тепер угорі пояснює, що він робить. Немає персонажа з професією Накладання чарів на акаунті? Він підкаже, куди надсилати предмети з позначкою «Розчаклувати»."
E["140:cdaafbc4"] = "матеріали, які дешевше виготовити самому (виплавити руду замість купівлі зливків...), рахуються за цією ціною - за рецептом, який знає один із ваших персонажів"
E["140:d2304b81"] = "Клацніть, щоб показати лише один тип рецептів за тим, що вони виготовляють - броня, зброя, зілля... Тип із частинами (нагрудник, поножі...) показує їх під собою."
E["140:e1402c2f"] = "У банку вікно Mastercraft («Забрати матеріали», «Здати матеріали») тепер з'являється поряд із вікном банку Baganator і кладе речі у вкладку, відкриту там."
E["142:0b94e65f"] = "«Сканувати ціни» читає весь аукціон за секунди. Тоді можна перевірити, скільки лотів на кожній ціні, тож купівля великої кількості показує справжню вартість."
E["142:3508ed73"] = "Поки ви ловите: звукові ефекти гучніші, музика й навколишній звук вимкнені, звук є навіть коли гра у фоні — усе повертається, коли ви зупинитесь."
E["142:68405c5a"] = "Найбільше оновлення в історії Mastercraft: відтепер він об'єднує гравців - тих, хто щось виготовляє, і тих, кому це потрібно."
E["142:8e9cb932"] = "У підземеллі, рейді, на полі бою чи арені прохання не спливають: вони чекають у «Запитах», а покупцям кажуть, що ви всередині, і вказують їхнє місце в черзі."
E["142:8f8768e9"] = "Звіт про помилки (Налаштування, /mc errors) тепер збирає лише помилки самого Mastercraft - помилки інших аддонів лишаються у власному вікні помилок гри."
E["142:e2ed7fe1"] = "Те, що є в одного з ваших персонажів, а іншому потрібне за його посібником з ремесла. Увійдіть тим, у кого це є, відкрийте поштову скриньку й натисніть «Пошта»."
E["143:34709576"] = "Позначені кроки зникають зі списку покупок, міні-посібника, поштової скриньки та підказок. Використайте, коли не можете отримати цей рецепт або підвищуєте рівень іншим способом."
E["143:94dce271"] = "Auctionator вимкнено або видалено, тож Mastercraft тепер використовує лише власне сканування цін. Увімкніть Auctionator знову будь-коли, щоб користуватися й його цінами."
E["143:feef257e"] = "Кнопка «Матеріали» на рецептах майстра і на знайденому вами рецепті: що потрібно, скільки є у ваших сумках і банку, та «Стежити за відсутніми»."
E["144:08ee18c1"] = "Зони фракції та спірні зони - міста й стартові зони іншої фракції пропущено. Усі: кожна зона. Запам'ятовується для цього персонажа."
E["144:48affb56"] = "Mastercraft тепер розмовляє й російською, французькою, іспанською, польською та португальською. Оберіть свою кнопкою-глобусом угорі праворуч або введіть /mc lang."
E["144:b534de49"] = "Натисніть око на рецепті - і маленьке спливне вікно повідомить, коли у мережі з'явиться майстер, що його виготовляє. Рецепти, за якими ви стежите, є в «Мій профіль майстра»."
E["144:d0472a64"] = "Маленька картка з уловом на мить — над панеллю риболовлі або високо посередині екрана. Риба, яку ви ніколи не ловили, про це скаже."
E["145:98f804a9"] = "Нічого надсилати: жоден ваш персонаж не має того, що потрібно для посібника іншого.\n\nПредмети з банку враховуються, коли ви відкриєте банк кожного персонажа."
E["146:3039efe5"] = "|cffeef0f5/mc|r  панель      |cffeef0f5/mc farm|r  трекер збору      |cffeef0f5/mc track|r  трекер предметів      |cffeef0f5/mc lang|r  мова"
E["146:a3c08dbf"] = "Шукайте рецепт, і кожен учасник гільдії з Mastercraft відповість, якщо хтось із його персонажів його знає.\nВаші власні персонажі теж враховано."
E["146:b19a8a1a"] = "Закидання, приманка, спорядження для риболовлі та гучніший сплеск в одному маленькому вікні. Воно відкривається саме, коли ви берете вудку. /mc fish теж його відкриває."
E["147:55f3401a"] = "Коли ви відкриваєте банк, вікно пропонує «Забрати матеріали» (матеріали, потрібні вашим посібникам, і те, що ви відстежуєте, - з банку до ваших сумок) та «Здати матеріали»."
E["147:5bf13047"] = "Налаштування > Ціни: кожне сканування цін перевіряє ще й 150 предметів Кодексу, спершу тих, що перевірялися найдавніше, тож кілька сканувань охоплюють кожен рецепт і матеріал."
E["147:775aa05f"] = "Оберіть, звідки беруться ціни: найновіші, спершу Mastercraft чи спершу Auctionator. Сканування Кодексу й нагадування про старі ціни тепер теж тут."
E["147:cc08e8d3"] = "Кожна кнопка показує свій напис повністю в кожній мові, заголовки лишаються в один рядок, а на рецепті кнопка «Картка рецепта» має верхній кут для себе."
E["148:4a565954"] = "Кожен похідний предмет кожної професії: що він робить, як його отримати (завдання, наставник чи креслення), що для цього потрібно - і де ви з кожним зараз."
E["148:84bc528e"] = "Дякуємо, що встановили Mastercraft! Кілька швидких кроків налаштують його під вас - усе можна змінити пізніше в налаштуваннях. Спершу ваша мова:"
E["148:87b3173f"] = "Налаштування > Загальне: кожне сканування цін перевіряє ще й 150 предметів Кодексу, спершу тих, що перевірялися найдавніше, тож кілька сканувань охоплюють кожен рецепт і матеріал."
E["149:44dddb03"] = "Підказує, яке зелене й синє спорядження продати торговцю або виставити на аукціон - і що робити з матеріалами та іншими товарами у ваших сумках."
E["149:af2480c9"] = "Предмети з позначкою Прив'язаний до душі ніколи не надсилаються на аукціон, а «Розчаклувати» радять лише коли ви маєте професію Накладання чарів - або коли предмет можна надіслати поштою тому, хто її має."
